import type { Root } from "postcss";
import type { PostcssResult } from "stylelint";
import { type ConfigurationError } from "../configurationError/index.ts";
/** The break rules whose run stands outside the text its lines are counted of — in front of a block, behind one, in front of a value — so a break written there leaves a single-line construct single-line. */
declare const NEWLINE_RULES_OUTSIDE_THE_COUNTED_TEXT: readonly [`block-opening-brace-newline-before`, `block-closing-brace-newline-after`, `declaration-colon-newline-after`];
